///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_registerId
 * @description register Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_registerId = async function () {
    const sbmOptions = {
        id: "tx_fn_registerId",
        method: "post",
        action: "/register/register.do?method=registerIntegUsrId",
        ref: "dma_registerIdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_checkUsrId
 * @description check Usr Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_checkUsrId = async function () {
    const sbmOptions = {
        id: "tx_fn_checkUsrId",
        method: "post",
        action: "/register/register.do?method=searchUsrId",
        ref: "dma_checkUsrIdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onChangeId
 * @description on Change Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.onChangeId = function () {
    $c.util.getComponent('ipt_message').setValue("");
    $("input[name='newYn']").val("");
};

/**
 * @method
 * @name logout
 * @description logout 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.logout = async function () {
    await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/logout.do?method=logout). 전환 대상 화면이 확정되면 연결됩니다.');
};

/**
 * @method
 * @name registerId
 * @description register Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerId = async function () {
    if (!await scwin.chkData()) {
        return false;
    }
    const SendForm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_telNo1').getValue()) === 0) {
        $c.util.getComponent("ipt_telNo1").setValue("00");
    }
    $c.util.getComponent('dma_registerIdReq').set('corpUsrNm', $c.util.getComponent('ipt_corpUsrNm1').getValue()+ ' [' + $c.util.getComponent('ipt_corpUsrNm2').getValue()+ ']');
    $c.util.getComponent('dma_registerIdReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent('dma_registerIdReq').set('encrypEmail', $c.util.getComponent('ipt_encrypEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypEmail2').getValue());
    scwin.form_SendForm.action = "/register/register.do?method=registerIntegUsrId";
    scwin.form_SendForm.target = "_self";
    await scwin.tx_fn_registerId();
};

/**
 * @method
 * @name chkData
 * @description chk Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkData = async function () {
    const SendForm = (document.SendForm || { elements: [] });
    if (((!$c.util.getComponent('ipt_perInfo1') || typeof $c.util.getComponent('ipt_perInfo1').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_perInfo1'), false) : ($c.util.getComponent('ipt_perInfo1').getValue() != null && String($c.util.getComponent('ipt_perInfo1').getValue()) !== '')) === false) {
        await $c.win.alert("개인정보 처리방침에 동의해주세요.");
        $c.util.getComponent("ipt_perInfo1").focus();
        return false;
    } else {
        if (((!$c.util.getComponent('ipt_perInfo2') || typeof $c.util.getComponent('ipt_perInfo2').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_perInfo2'), false) : ($c.util.getComponent('ipt_perInfo2').getValue() != null && String($c.util.getComponent('ipt_perInfo2').getValue()) !== '')) === false) {
            await $c.win.alert("개인정보 수집 및 이용에 동의해주세요.");
            $c.util.getComponent("ipt_perInfo2").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_integUsrId').getValue().replace(/ /gi, "")) === 0) {
                await $c.win.alert("아이디를 입력하십시오.");
                $c.util.getComponent("ipt_integUsrId").setValue("");
                $c.util.getComponent("ipt_integUsrId").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('dma_registerIdReq').get('newYn').replace(/ /gi, "")) === 0) {
                    await $c.win.alert("아이디 중복확인 여부를 확인하십시오.");
                    return false;
                } else {
                    if ($c.util.getComponent('dma_registerIdReq').get('newYn') !== "Y") {
                        await $c.win.alert("다른 아이디를 입력하십시오.");
                        $c.util.getComponent("ipt_integUsrId").setValue("");
                        $c.util.getComponent("ipt_integUsrId").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('ipt_corpUsrNm2').getValue()) === 0) {
                            await $c.win.alert("소속기관을 입력하십시오.");
                            $c.util.getComponent("ipt_corpUsrNm2").focus();
                            return false;
                        } else {
                            if ($c.str.getByteLength($c.util.getComponent('ipt_corpUsrNm1').getValue()) === 0) {
                                await $c.win.alert("이름을 입력하십시오.");
                                $c.util.getComponent("ipt_corpUsrNm1").focus();
                                return false;
                            } else {
                                if ($c.str.getByteLength($c.util.getComponent('ipt_telNo2').getValue()) === 0 || $c.str.getByteLength($c.util.getComponent('ipt_telNo3').getValue()) === 0) {
                                    await $c.win.alert("전화번호를 입력하십시오.");
                                    $c.util.getComponent("ipt_telNo1").focus();
                                    return false;
                                } else {
                                    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypEmail1').getValue()) === 0) {
                                        await $c.win.alert("이메일을 입력하십시오.");
                                        $c.util.getComponent("ipt_encrypEmail1").focus();
                                        return false;
                                    } else {
                                        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypEmail2').getValue()) === 0) {
                                            await $c.win.alert("이메일을 입력하십시오.");
                                            $c.util.getComponent("ipt_encrypEmail2").focus();
                                            return false;
                                        } else {
                                            if (!$c.str.isEmail($c.util.getComponent('ipt_encrypEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypEmail2').getValue())) {
                                                await $c.win.alert("이메일이 올바르지 않습니다.");
                                                $c.util.getComponent("ipt_encrypEmail2").focus();
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return true;
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name checkUsrIdDone
 * @description check Usr Id Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.checkUsrIdDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_message').setValue(result.message);
    $("input[name='newYn']").val(result.newYn);
};

/**
 * @method
 * @name checkUsrId
 * @description check Usr Id 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkUsrId = async function () {
    const r = await scwin.tx_fn_checkUsrId();
    try {
        scwin.checkUsrIdDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf55301.fn_checkUsrId' });
    }
    return r;
};
